// Turn the uploaded file into clean text plus the meeting facts that the prompt
// and the Doc need. Anything that can be rejected before paying for a model call
// is rejected here.

const MIN_SPEAKER_LINES = 3;
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

const cfg = $('Set configuration').first().json;
const formItem = $('Upload transcript via form').first();
const form = formItem.json;

if (!cfg.notesDocId || String(cfg.notesDocId).startsWith('YOUR_')) {
  throw new Error('notesDocId is still a placeholder. Open Set configuration and paste the ID of your meeting notes Google Doc (the long part of its URL between /d/ and /edit).');
}

const members = String(cfg.teamMembers || '').split(',').map((s) => s.trim()).filter(Boolean);
if (!members.length) {
  throw new Error('teamMembers is empty. Open Set configuration and list the attendees, separated by commas.');
}

const maxChars = Number(cfg.maxTranscriptChars) || 200000;
const tz = String(cfg.timezone || 'UTC').trim();

// --- Dates, all as YYYY-MM-DD strings in the configured timezone -------------

function isRealDate(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) return false;
  const d = new Date(s + 'T12:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === s;
}

function partsInTz(date) {
  let fmt;
  try {
    fmt = new Intl.DateTimeFormat('en-GB', {
      timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
    });
  } catch (e) {
    throw new Error('timezone "' + tz + '" is not a valid IANA timezone. Use a name like Europe/London or America/New_York in Set configuration.');
  }
  const p = {};
  for (const part of fmt.formatToParts(date)) p[part.type] = part.value;
  return p;
}

function addDays(iso, n) {
  const d = new Date(iso + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

const weekdayOf = (iso) => new Date(iso + 'T12:00:00Z').getUTCDay();

const submitted = form.submittedAt ? new Date(form.submittedAt) : new Date();
const uploadMoment = isNaN(submitted) ? new Date() : submitted;
const up = partsInTz(uploadMoment);
const uploadDate = up.year + '-' + up.month + '-' + up.day;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const uploadedAt = Number(up.day) + ' ' + MONTHS[Number(up.month) - 1] + ' ' + up.year + ' ' + up.hour + ':' + up.minute;

// --- The uploaded file -------------------------------------------------------

// n8n stores uploads either in the item's binary section or, in the newer
// "combined" binary mode, as an object inside the JSON. Look in both places, on
// this node's input and on the form itself, so either setting works.
const isFile = (v) => v && typeof v === 'object' && 'mimeType' in v && ('data' in v || 'id' in v);

function findFile(it) {
  if (!it) return null;
  const bin = it.binary || {};
  if (isFile(bin.Transcript)) return bin.Transcript;
  const firstBin = Object.values(bin).find(isFile);
  if (firstBin) return firstBin;
  const json = it.json || {};
  if (isFile(json.Transcript)) return json.Transcript;
  return Object.values(json).find(isFile) || null;
}

const file = findFile($input.first()) || findFile(formItem);
if (!file) {
  throw new Error('No file arrived with the form submission. Upload the transcript as a .txt file and submit again.');
}

const fileName = String(file.fileName || 'transcript.txt');
const mimeType = String(file.mimeType || '').toLowerCase();
const isTxt = /\.txt$/i.test(fileName) || mimeType.startsWith('text/plain');
if (!isTxt) {
  throw new Error('"' + fileName + '" is not a .txt file (' + (mimeType || 'unknown type') + '). Export the transcript as plain text and upload that.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, file);
let text = buffer.toString('utf8');

if (text.includes('\u0000')) {
  throw new Error('"' + fileName + '" contains binary data, so it is not a plain-text transcript. Export it as .txt and upload again.');
}

text = text
  .replace(/^﻿/, '')
  .replace(/\r\n?/g, '\n')
  .replace(/[ \t ]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!text) {
  throw new Error('"' + fileName + '" is empty. Check the export from your recording tool and upload the transcript again.');
}
if (text.length > maxChars) {
  throw new Error('"' + fileName + '" has ' + text.length + ' characters, over the limit of ' + maxChars + ' (maxTranscriptChars in Set configuration). Split the transcript or raise the limit.');
}

// --- Meeting date: form, then filename prefix, then the upload date ----------

const formDate = String(form['Meeting date'] || '').trim().slice(0, 10);
const prefix = fileName.match(/^(\d{4}-\d{2}-\d{2})(?=[\s_.-])/);

let meeting_date;
let date_source;
if (formDate) {
  if (!isRealDate(formDate)) {
    throw new Error('The meeting date "' + form['Meeting date'] + '" is not a real date. Pick it from the date picker or leave it blank.');
  }
  meeting_date = formDate;
  date_source = 'form';
} else if (prefix && isRealDate(prefix[1])) {
  meeting_date = prefix[1];
  date_source = 'filename';
} else {
  meeting_date = uploadDate;
  date_source = 'upload_date';
}

// --- Meeting title: form, else the cleaned-up filename ------------------------

const formTitle = String(form['Meeting title'] || '').trim();
const fileTitle = fileName
  .replace(/\.[^.]+$/, '')
  .replace(/^\d{4}-\d{2}-\d{2}[\s_-]*/, '')
  .replace(/\s*-\s*Recording Transcript(\s*\(\d+\))?\s*$/i, '')
  .trim();
const meeting_title = formTitle || fileTitle || 'Meeting';

// --- Next meeting, for "by the next meeting" ---------------------------------

const meetingDayIdx = String(cfg.meetingDays || '')
  .split(',')
  .map((d) => d.trim())
  .filter((d) => d.length >= 3)
  .map((d) => WEEKDAYS.findIndex((w) => w.toLowerCase().startsWith(d.trim().toLowerCase().slice(0, 3))))
  .filter((i) => i >= 0 && i < 7);

let next_meeting_date = null;
if (meetingDayIdx.length) {
  for (let n = 1; n <= 7; n++) {
    const candidate = addDays(meeting_date, n);
    if (meetingDayIdx.includes(weekdayOf(candidate))) {
      next_meeting_date = candidate;
      break;
    }
  }
}

// --- Speaker labels: "Name: text" lines where Name is a team member ----------

const lowerMembers = members.map((m) => m.toLowerCase());
const labelledLines = text.split('\n').filter((line) => {
  const m = line.match(/^([^:\n]{1,40}):\s+\S/);
  return m && lowerMembers.includes(m[1].trim().toLowerCase());
}).length;

return [{
  json: {
    fileName,
    uploadedAt,
    meeting_date,
    meeting_weekday: WEEKDAYS[weekdayOf(meeting_date)],
    next_meeting_date,
    date_source,
    meeting_title,
    attendees: members,
    speaker_labelled: labelledLines >= MIN_SPEAKER_LINES,
    transcript: text,
    char_count: text.length,
    word_count: text.split(/\s+/).filter(Boolean).length,
  },
}];

// Build the OpenRouter request. The rules here mirror the checks in Validate
// Claude notes, so a well-behaved answer passes first time. Edit both together.

const cfg = $('Set configuration').first().json;
const m = $input.first().json;
const maxWords = Number(cfg.maxSummaryWords) || 500;

const nextMeeting = m.next_meeting_date
  ? 'The next meeting is ' + m.next_meeting_date + '.'
  : 'The next meeting date is not known, so "by the next meeting" has no date.';

const speakers = m.speaker_labelled
  ? 'Lines starting with "Name:" are labelled with the speaker, so you may use those names as owners when that person takes on a task.'
  : 'The transcript has NO speaker labels, so you cannot tell who said "I will do it".';

const systemPrompt = [
  'You are the note-taker for ' + (cfg.organisationName || 'the organisation') + '.',
  'Attendees: ' + m.attendees.join(', ') + '.',
  'The meeting date is ' + m.meeting_date + ' (' + m.meeting_weekday + '). The team usually meets on ' + (cfg.meetingDays || 'no fixed days') + '. ' + nextMeeting,
  '',
  'The transcript is machine-generated speech-to-text with frequent mis-transcriptions. ' + speakers,
  'Read through obvious transcription errors. Glossary of terms the transcriber gets wrong: ' + (cfg.glossary || 'none') + '.',
  'Never invent facts, names, numbers or dates. If something is unclear, leave it out.',
  '',
  'SUMMARY',
  '- agenda: the topics actually discussed, in the order discussed, as short titles.',
  '- topics: one entry per agenda item, with exactly the same title as in agenda, in the same order, each with 1 to 6 short bullet points on what was discussed.',
  '- Decisions start with "Decision: ". Ideas floated but not agreed may be mentioned as such.',
  '- The whole summary (agenda entries + topic titles + bullets) must be at most ' + maxWords + ' words.',
  '',
  'ACTION ITEMS',
  '- Only work that someone agreed to do, or that the team agreed must be done. Options that were only floated are not action items.',
  '- task: one or two plain sentences, at most 45 words, starting with a verb and stating the deliverable so someone who missed the meeting knows what "done" looks like.',
  '- owner: one of ' + JSON.stringify(m.attendees) + ' only if the transcript names that person as doing it' + (m.speaker_labelled ? ' or their labelled line takes it on' : '') + '. Otherwise exactly "Unassigned".',
  '- due_date: YYYY-MM-DD, resolved against the meeting date. A spoken date with no year means the next occurrence on or after the meeting date. Never before the meeting date.',
  '- due_basis: "stated" when a date was said, "inferred: <short reason>" when you worked it out (for example "inferred: next meeting"), or "none" with due_date null when no date was agreed. Never invent a deadline.',
  '',
  'Return only a JSON object, no markdown fences, in this shape:',
  '{"agenda":[string],"topics":[{"title":string,"bullets":[string]}],"action_items":[{"task":string,"owner":string,"due_date":string|null,"due_basis":string}]}',
  'If no action items were agreed, return "action_items": [].',
].join('\n');

const body = {
  model: cfg.aiModel,
  temperature: 0.2,
  max_tokens: 8000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    {
      role: 'user',
      content: 'Meeting: ' + m.meeting_title + ' (' + m.meeting_date + ')\n\nTranscript:\n<<<\n' + m.transcript + '\n>>>',
    },
  ],
};

return [{ json: { meeting_title: m.meeting_title, requestBody: JSON.stringify(body) } }];

// Check Claude's answer against every rule before anything touches the Doc.
// All problems are collected and reported together, so one failed run shows
// everything that was wrong.

const MAX_TASK_SENTENCES = 2;
const MAX_TASK_WORDS = 45;

const cfg = $('Set configuration').first().json;
const meeting = $('Prepare transcript and meeting details').first().json;
const res = $input.first().json;
const maxWords = Number(cfg.maxSummaryWords) || 500;

if (res.error) {
  throw new Error('OpenRouter returned an error: ' + (res.error.message || JSON.stringify(res.error)) + '. Check the credential, the aiModel slug and your OpenRouter credit.');
}

const choice = res.choices && res.choices[0];
const raw = choice && choice.message && choice.message.content;
if (!raw) {
  throw new Error('OpenRouter returned no message content. Response: ' + JSON.stringify(res).slice(0, 300));
}
if (choice.finish_reason === 'length') {
  throw new Error('Claude ran out of output tokens before finishing the notes, so the answer is cut off. Run the form again, or raise max_tokens in Build Claude request.');
}

const words = (s) => String(s || '').split(/\s+/).filter(Boolean).length;
const sentences = (s) => String(s || '').trim().split(/(?<=[.!?])\s+(?=["'(\[]?[A-Z0-9])/).filter((x) => x.trim()).length;
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const isRealDate = (s) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s))) return false;
  const d = new Date(s + 'T12:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === s;
};

let text = String(raw).replace(/```(?:json)?/gi, '').trim();
const first = text.indexOf('{');
const last = text.lastIndexOf('}');
if (first > 0 || (last !== -1 && last < text.length - 1)) text = text.slice(first, last + 1);

let notes;
try {
  notes = JSON.parse(text);
} catch (e) {
  throw new Error('Claude\'s answer is not valid JSON, so the Doc was not changed. Run the form again. Start of the answer: ' + text.slice(0, 300));
}

const problems = [];

if (!notes || typeof notes !== 'object' || Array.isArray(notes)) {
  problems.push('the answer is not a JSON object');
  notes = {};
}
if (!Array.isArray(notes.agenda)) problems.push('agenda is missing or not a list');
if (!Array.isArray(notes.topics)) problems.push('topics is missing or not a list');
if (!Array.isArray(notes.action_items)) problems.push('action_items is missing or not a list');

const agenda = Array.isArray(notes.agenda) ? notes.agenda : [];
const topics = Array.isArray(notes.topics) ? notes.topics : [];
const items = Array.isArray(notes.action_items) ? notes.action_items : [];

// Summary
let summaryWords = 0;
agenda.forEach((a, i) => {
  if (typeof a !== 'string' || !a.trim()) problems.push('agenda[' + i + '] is empty or not text');
  summaryWords += words(a);
});
topics.forEach((t, i) => {
  if (!t || typeof t.title !== 'string' || !t.title.trim()) problems.push('topics[' + i + '].title is empty');
  summaryWords += words(t && t.title);
  const bullets = t && Array.isArray(t.bullets) ? t.bullets : [];
  if (!bullets.length) problems.push('topics[' + i + '] has no bullets');
  bullets.forEach((b, j) => {
    if (typeof b !== 'string' || !b.trim()) problems.push('topics[' + i + '].bullets[' + j + '] is empty or not text');
    summaryWords += words(b);
  });
});
if (summaryWords > maxWords) problems.push('the summary has ' + summaryWords + ' words (max ' + maxWords + ')');

if (agenda.length !== topics.length) {
  problems.push('agenda has ' + agenda.length + ' entries but topics has ' + topics.length + ' (they must match one-to-one)');
} else {
  agenda.forEach((a, i) => {
    if (norm(a) !== norm(topics[i] && topics[i].title)) {
      problems.push('agenda[' + i + '] "' + a + '" does not match topics[' + i + '].title "' + (topics[i] && topics[i].title) + '"');
    }
  });
}

// Action items
const owners = new Map(meeting.attendees.map((n) => [n.toLowerCase(), n]));
owners.set('unassigned', 'Unassigned');

const cleanItems = items.map((it, i) => {
  const at = 'action_items[' + i + ']';
  if (!it || typeof it !== 'object') {
    problems.push(at + ' is not an object');
    return null;
  }

  const task = String(it.task || '').trim();
  if (!task) problems.push(at + '.task is empty');
  else {
    const s = sentences(task);
    const w = words(task);
    if (s > MAX_TASK_SENTENCES) problems.push(at + '.task has ' + s + ' sentences (max ' + MAX_TASK_SENTENCES + ')');
    if (w > MAX_TASK_WORDS) problems.push(at + '.task has ' + w + ' words (max ' + MAX_TASK_WORDS + ')');
  }

  const owner = owners.get(String(it.owner || '').trim().toLowerCase());
  if (!owner) problems.push(at + '.owner "' + it.owner + '" is not a team member or "Unassigned"');

  const basisRaw = String(it.due_basis || '').trim();
  const basisLower = basisRaw.toLowerCase();
  let basis = null;
  if (basisLower === 'stated') basis = 'stated';
  else if (basisLower === 'none') basis = 'none';
  else if (/^inferred\s*:\s*\S/.test(basisLower)) basis = 'inferred: ' + basisRaw.replace(/^inferred\s*:\s*/i, '');
  else problems.push(at + '.due_basis "' + basisRaw + '" must be "stated", "inferred: <reason>" or "none"');

  const due = it.due_date === undefined || it.due_date === null || it.due_date === '' ? null : String(it.due_date).trim();
  if (due !== null) {
    if (!isRealDate(due)) problems.push(at + '.due_date "' + due + '" is not a real YYYY-MM-DD date');
    else if (due < meeting.meeting_date) problems.push(at + '.due_date ' + due + ' is before the meeting date ' + meeting.meeting_date);
    if (basis === 'none') problems.push(at + '.due_date is set but due_basis is "none"');
  } else if (basis && basis !== 'none') {
    problems.push(at + '.due_date is empty but due_basis is "' + basis + '"');
  }

  return { task, owner: owner || 'Unassigned', due_date: due, due_basis: basis || 'none' };
});

if (problems.length) {
  throw new Error(
    'Claude\'s notes failed ' + problems.length + ' check(s), so the Doc was not changed:\n- ' +
    problems.join('\n- ') +
    '\nRun the form again. If the same check keeps failing, loosen the limit in Set configuration or adjust the prompt in Build Claude request.'
  );
}

return [{
  json: {
    notes: {
      agenda: agenda.map((a) => a.trim()),
      topics: topics.map((t) => ({ title: t.title.trim(), bullets: t.bullets.map((b) => b.trim()) })),
      action_items: cleanItems,
    },
    summary_words: summaryWords,
  },
}];

// Build this meeting's notes as HTML and put them at the top of the exported
// Doc. Drive converts the HTML back into real headings, lists and a table on
// upload. Earlier meetings stay below, under a horizontal rule.

const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MONTHS_SHORT = MONTHS_LONG.map((m) => m.slice(0, 3));

const meeting = $('Prepare transcript and meeting details').first().json;
const notes = $('Validate Claude notes').first().json.notes;
const existing = String($input.first().json.data || '');

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const fmtDate = (iso, months) => {
  const [y, m, d] = iso.split('-').map(Number);
  return d + ' ' + months[m - 1] + ' ' + y;
};

const DATE_NOTES = {
  form: '',
  filename: ' (from the filename)',
  upload_date: ' (date not given, used the upload date)',
};

const cell = 'style="border:1px solid #999999;padding:4pt 6pt;vertical-align:top"';
const head = 'style="border:1px solid #999999;padding:4pt 6pt;background-color:#eeeeee;text-align:left"';

const html = [];
html.push('<h1>' + esc(meeting.meeting_title) + '</h1>');
html.push('<p>Date: ' + esc(fmtDate(meeting.meeting_date, MONTHS_LONG) + DATE_NOTES[meeting.date_source]) +
  ' · Attendees: ' + esc(meeting.attendees.join(', ')) + '</p>');
html.push('<p>Source: ' + esc(meeting.fileName) + ', uploaded ' + esc(meeting.uploadedAt) + '</p>');
html.push('<p><i>Generated by n8n with Claude. Check it before relying on it.</i></p>');

html.push('<h2>Summary</h2>');
html.push('<h3>Agenda</h3>');
html.push('<ol>' + notes.agenda.map((a) => '<li>' + esc(a) + '</li>').join('') + '</ol>');
for (const t of notes.topics) {
  html.push('<h3>' + esc(t.title) + '</h3>');
  html.push('<ul>' + t.bullets.map((b) => '<li>' + esc(b) + '</li>').join('') + '</ul>');
}

html.push('<h2>Action items</h2>');
const items = notes.action_items;
if (!items.length) {
  html.push('<p>No action items were agreed.</p>');
} else {
  const due = (it) => {
    if (!it.due_date) return 'Not agreed';
    const basis = it.due_basis === 'stated' ? 'stated' : it.due_basis;
    return fmtDate(it.due_date, MONTHS_SHORT) + ' (' + basis + ')';
  };
  const rows = items.map((it, i) => '<tr>' +
    '<td ' + cell + '>' + (i + 1) + '</td>' +
    '<td ' + cell + '>' + esc(it.task) + '</td>' +
    '<td ' + cell + '>' + esc(it.owner) + '</td>' +
    '<td ' + cell + '>' + esc(fmtDate(meeting.meeting_date, MONTHS_SHORT)) + '</td>' +
    '<td ' + cell + '>' + esc(due(it)) + '</td>' +
    '</tr>');
  html.push('<table style="border-collapse:collapse;width:100%"><tr>' +
    ['#', 'Task', 'Owner', 'Assigned', 'Due'].map((h) => '<th ' + head + '>' + h + '</th>').join('') +
    '</tr>' + rows.join('') + '</table>');
}

const unassigned = items.filter((it) => it.owner === 'Unassigned').length;
if (unassigned) {
  html.push('<p><b>Needs an owner:</b> ' + unassigned + ' of ' + items.length + ' action items have no owner.</p>');
}

const section = html.join('\n');

// Insert straight after <body>, keeping the export's <head> styles so earlier
// meetings keep their formatting. An empty Doc exports with an empty body.
const bodyTag = existing.match(/<body[^>]*>/i);
let output;
if (bodyTag) {
  const at = bodyTag.index + bodyTag[0].length;
  const rest = existing.slice(at);
  const hasContent = rest.replace(/<\/body>[\s\S]*$/i, '').replace(/<[^>]+>/g, '').replace(/&nbsp;|\s/g, '').length > 0;
  output = existing.slice(0, at) + '\n' + section + (hasContent ? '\n<hr>\n' : '\n') + rest;
} else if (!existing.replace(/<[^>]+>/g, '').trim()) {
  output = '<html><head><meta charset="utf-8"></head><body>\n' + section + '\n</body></html>';
} else {
  throw new Error('The notes Doc export did not look like HTML, so it was not changed. Check that notesDocId points at a Google Doc, not a Word file or a folder.');
}

return [{
  json: {
    html: output,
    meeting_title: meeting.meeting_title,
    meeting_date: meeting.meeting_date,
    action_items: items.length,
    unassigned,
  },
}];
